Solution B: function generateMap(canvasId) {
    const canvas = document.getElementById(canvasId);
    const ctx = canvas.getContext('2d');
    const W = canvas.width;
    const H = canvas.height;
    const CELL = 5; // each cell 5x5 pixels
    const COLS = W / CELL;
    const ROWS = H / CELL;

    // 0 = empty, 1 = floor, 2 = wall
    const map = new Uint8Array(COLS * ROWS);
    function set(x, y, v) { map[y * COLS + x] = v; }
    function get(x, y) { return map[y * COLS + x]; }

    // ---------- BSP Room Generation ----------
    const rooms = [];
    function split(node, depth) {
        if (depth <= 0) {
            const margin = 2;
            const w = node.w - margin * 2;
            const h = node.h - margin * 2;
            const rx = node.x + margin;
            const ry = node.y + margin;
            rooms.push({x:rx, y:ry, w:w, h:h});
            return;
        }
        const horiz = Math.random() < 0.5;
        if (horiz) {
            const splitY = node.y + Math.floor(node.h * 0.3) + Math.floor(Math.random()*Math.floor(node.h*0.));
            split({x:node.x, y:node.y, w:node.w, h:splitY-node.y}, depth-1);
            split({x:node.x, y:splitY, w:node.w, h:node.y+node.h-splitY}, depth-1);
        } else {
            const splitX = node.x + Math.floor(node.w * 0.3) + Math.floor(Math.random()*Math.floor(node.w*0.4));
            split({x:node.x, y:node.y, w:splitX-node.x, h:node.h}, depth-1);
            split({x:splitX, y:node.y, w:node.x+node.w-splitX, h:node.h}, depth-1);
        }
    }
    split({x:2, y:2, w:COLS-4, h:ROWS-4}, 4);

    // ---------- Fill Rooms ----------
    rooms.forEach(r => {
        for (let y = r.y; y < r.y + r.h; y++) {
            for (let x = r.x; x < r.x + r.w; x++) {
                set(x, y, 1); // floor
            }
        }
    });

    // ---------- Connect Rooms ----------
    function connect(a, b) {
        const x1 = Math.floor(a.x + a.w/2);
        const y1 = Math.floor(a.y + a.h/2);
        const x2 = Math.floor(b.x + b.w/2);
        const y2 = Math.floor(b.y + b.h/2);
        let x = x1, y = y1;
        while (x !== x2) {
            set(x, y, 1);
            x += x < x2 ? 1 : -1;
        }
        while (y !== y2) {
            set(x, y, 1);
            y += y < y2 ? 1 : -1;
        }
    }
    for (let i = 1; i < rooms.length; i++) {
        connect(rooms[i-1], rooms[i]);
    }

    // ---------- Walls ----------
    for (let y = 1; y < ROWS-1; y++) {
        for (let x = 1; x < COLS-1; x++) {
            if (get(x, y) === 1) {
                for (let dy = -1; dy <= 1; dy++) {
                    for (let dx = -1; dx <= 1; dx++) {
                        if (get(x+dx, y+dy) === 0) set(x+dx, y+dy, 2);
                    }
                }
            }
        }
    }

    // ---------- Flood Fill Connectivity ----------
    const visited = new Uint8Array(COLS * ROWS);
    const queue = [];
    // start from center of first room
    const startX = Math.floor(rooms[0].x + rooms[0].w/2);
    const startY = Math.floor(rooms[0].y + rooms[0].h/2);
    queue.push(startX, startY);
    visited[startY*COLS+startX] = 1;
    while (queue.length) {
        const y = queue.pop();
        const x = queue.pop();
        const dirs = [[1,0],[-1,0],[0,1],[0,-1]];
        for (const [dx,dy] of dirs) {
            const nx = x+dx, ny = y+dy;
            if (nx<0||ny<0||nx>=COLS||ny>=ROWS) continue;
            const idx = ny*COLS+nx;
            if (visited[idx]) continue;
            if (get(nx,ny)===1) {
                visited[idx]=1;
                queue.push(nx,ny);
            }
        }
    }
    // connect any unvisited floor tiles
    for (let y = 0; y < ROWS; y++) {
        for (let x = 0; x < COLS; x++) {
            if (get(x,y)===1 && !visited[y*COLS+x]) {
                // carve a path from start to this tile
                let cx = startX, cy = startY;
                while (cx !== x) { set(cx,cy,1); cx += cx<x?1:-1; }
                while (cy !== y) { set(cx,cy,1); cy += cy<y?1:-1; }
                visited[y*COLS+x]=1;
            }
        }
    }

    // ---------- Spawn Points & Weapon Pickups ----------
    function randomFloor() {
        while (true) {
            const x = Math.floor(Math.random()*COLS);
            const y = Math.floor(Math.random()*ROWS);
            if (get(x,y)===1) return {x,y};
        }
    }
    const spawnPoints = [];
    for (let i = 0; i < 2; i++) spawnPoints.push(randomFloor());
    const weapons = [];
    for (let i = 0; i < 3; i++) weapons.push(randomFloor());

    // ---------- Rendering ----------
    ctx.clearRect(0,0,W,H);
    for (let y = 0; y < ROWS; y++) {
        for (let x = 0; x < COLS; x++) {
            const v = get(x,y);
            if (v===2) ctx.fillStyle = '#000';
            else if (v===1) ctx.fillStyle = '#777';
            else continue;
            ctx.fillRect(x*CELL, y*CELL, CELL, CELL);
        }
    }
    // spawn points
    ctx.fillStyle = '#0f0';
    spawnPoints.forEach(p => ctx.fillRect(p.x*CELL, p.y*CELL, CELL, CELL));
    // weapons
    ctx.fillStyle = '#f00';
    weapons.forEach(p => ctx.fillRect(p.x*CELL, p.y*CELL, CELL, CELL));
}

